  steps = '[
    {"type":"lesson","emoji":"🤖","title":"Il ML Vale Quando Lo Tratti Come Componente Ingegneristico","content":"Un modello di machine learning non è una magia isolata. Ha dati di training, assunzioni, metriche, failure mode, costi computazionali e limiti di generalizzazione. Il suo valore dipende da come lo inserisci in un sistema che sa monitorarlo e compensarne i limiti.","key_points":["Il modello ha un dominio di validità","Metriche offline non bastano da sole","Il ML va letto insieme a fallback e monitoraggio"],"references":[{"title":"ML systems basics","url":"https://www.youtube.com/results?search_query=machine+learning+systems+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"trade-study","title":"ML as system block","caption":"Accuratezza, latenza, costo e robustezza si bilanciano come proprietà del sottosistema."}]},
    {"type":"fill-blank","emoji":"📚","sentence":"Un modello che funziona bene sui dati di training ma male sul mondo reale soffre di scarsa ___.","options":["generalizzazione","grafica","compressione","memoria video"],"correct":0,"explanation":"La generalizzazione misura quanto bene il modello regge dati e condizioni non identici al training."},
    {"type":"challenge","title":"Modello Accurate ma Fragile","scenario":"Un classificatore ha ottime metriche offline, ma in condizioni operative rumorose degrada proprio nelle classi più costose.","question":"Qual e la lettura piu forte?","options":["Le metriche medie bastano","Il modello va letto rispetto al dominio operativo reale e ai failure mode più costosi","Serve solo più dataset senza analisi","La GPU è troppo lenta"],"correct":1,"explanation":"Il valore del modello dipende dal suo comportamento nei casi ad alta conseguenza e fuori nominale, non solo dalla media."},
    {"type":"sorting","title":"Valutare un Blocco ML","emoji":"🧪","question":"Ordina i passaggi piu maturi per valutare un componente ML in un sistema reale.","items":["Definire compito, costo dell errore e dominio operativo","Valutare dati, metriche e generalizzazione","Capire latenza, compute e integrazione col resto del sistema","Definire monitoraggio, fallback e limiti operativi"],"explanation":"Prima chiarisci il dominio, poi la qualità del modello, poi l integrazione e infine la gestione del degrado."},
    {"type":"design","title":"Design Review: ML in Loop Operativo","brief":"Vuoi inserire un componente ML in un sistema con rischio fisico o operativo non banale.","constraints":["Il modello non e infallibile","La latenza conta","Serve comportamento prudente sotto bassa confidenza","Il sistema deve restare verificabile"],"question":"Qual e la postura piu matura?","options":["Usare il modello come verità finale","Inserire il modello come blocco monitorato con limiti, fallback e contesto di utilizzo espliciti","Ignorare la confidenza del modello","Guardare solo l accuracy media"],"correct":1,"explanation":"Il ML credibile vive dentro un architettura che ne delimita il dominio e ne contiene gli errori.","tradeoffs":["Piu accuratezza può costare latenza o opacità","Piu guardrail possono ridurre aggressivita del sistema","La verificabilità del blocco vale quanto la sua performance media"],"references":[{"title":"Robust ML systems","url":"https://www.youtube.com/results?search_query=robust+ml+systems","type":"video","source":"YouTube"}]}
  ]'::jsonb
where title = 'Machine Learning per Ingegneri'
  and path_id = (select id from public.learning_paths where slug = 'ai-simulation');
